/**
 * Read-models over the cached upstream catalogue for the discovery
 * built-ins — `describe_upstream`, `list_upstreams`,
 * `list_my_context.restrictedTools` — plus the server-instructions
 * guidance tail and the pure description/grouping helpers they share
 * with tool registration (`proxy-registry.ts`). Cache-only: nothing
 * here dials an upstream.
 */

import type { Env } from '../env'
import {
  getUpstreamVisibleToUser,
  listUpstreamsVisibleToUser,
  type UpstreamServerRow
} from '../db/queries/upstreams'
import {
  countToolsForUpstreams,
  listCachedTools,
  listCachedToolsForUpstreams,
  type UpstreamToolRow
} from '../db/queries/upstream-tools'
import { getUserCredentialStatuses } from '../db/queries/upstream-credentials'
import {
  listSkillsForUpstream,
  listSkillsForUpstreams,
  type SkillForUpstreamRow
} from '../db/queries/skill-attachments'
import {
  listDocsForUpstream,
  listDocsForUpstreams,
  type DocForUpstreamRow
} from '../db/queries/doc-attachments'
import {
  accessKey,
  indexToolAccess,
  listToolAccessForUpstream,
  listToolAccessForUpstreams,
  resolveUserPrincipals
} from '../db/queries/tool-access'
import { isDialableTransport } from '../upstream/upstream-client'
import {
  isToolAllowed,
  requiresFromRules,
  type McpAttachedDocRef,
  type McpAttachedSkillRef,
  type McpRestrictedTool,
  type McpUpstreamEntry,
  type McpUpstreamToolGroup,
  type McpUpstreamTools,
  type SupportedTransport,
  type UserPrincipals
} from '@ctxlayer/shared'
import { mangleToolName, toolFamily } from './tool-name'
import { sanitizeUntrustedText } from './provenance'

// The `list_upstreams` entry shape is the shared MCP output contract; the
// builder below is typed against it so it can't drift from the schema.
export type ListUpstreamsEntry = McpUpstreamEntry

/**
 * The visible-upstream rows + their skill/doc attachments for one user,
 * fetched in 3 round trips total (one list + two `IN (...)` batches).
 * Loaded once per session init and shared between `upstreamGuidance`
 * (server instructions) and registry `init` (tool registration) so
 * neither re-runs the visibility query or the per-upstream attachment
 * reads.
 */
export interface UpstreamUserContext {
  rows: UpstreamServerRow[]
  skillsByUpstream: Map<string, SkillForUpstreamRow[]>
  docsByUpstream: Map<string, DocForUpstreamRow[]>
}

/**
 * The visible upstreams + their attachments for one user, in 3 D1
 * round trips. `McpSessionDO.init()` loads this once and feeds it to
 * both `upstreamGuidance` and the registry's `init`.
 */
export async function loadUserContext(env: Env, userId: string): Promise<UpstreamUserContext> {
  const rows = await listUpstreamsVisibleToUser(env, userId)
  const ids = rows.map((r) => r.id)
  const [skillsByUpstream, docsByUpstream] = await Promise.all([
    listSkillsForUpstreams(env, ids),
    listDocsForUpstreams(env, ids)
  ])
  return { rows, skillsByUpstream, docsByUpstream }
}

const GUIDANCE_HEADER =
  '**Org playbooks for your upstreams — read the named skill/doc BEFORE the ' +
  'first call to that upstream (fetch via `get_skill` / `get_doc`; required ' +
  'conventions the tool schemas do not show):**\n'

/** Refs named per upstream line before collapsing into `+N more`. */
const MAX_REFS_PER_LINE = 3

/**
 * Builds the LEADING block of the MCP server `instructions`: one line
 * per visible upstream that carries a *whole-upstream* skill/doc
 * attachment (tool_name = ''), naming each so the agent reads the org
 * playbook before its first call. Returns '' when nothing is attached;
 * otherwise ends with a blank line so the static base reads on from it.
 * It goes FIRST because clients truncate long instructions and a
 * trailing tail is exactly what gets cut — see the size-budget note in
 * server-instructions.ts.
 *
 * `budget` (chars, normally GUIDANCE_BUDGET) bounds the block for ANY
 * attachment count: refs collapse to `+N more` past MAX_REFS_PER_LINE,
 * and when whole lines no longer fit the rest degrade to one pointer at
 * `list_upstreams.attached_skills` — the structured second step — so
 * growth can never push the static base past the client cap. Which
 * upstreams get named under collapse is row order (the visibility-query
 * order); nothing smarter until a real org hits it.
 * The slugs are org-curated (kebab-case, first-party) — unlike upstream
 * tool descriptions they are not untrusted input, so no sanitisation.
 * Pure formatting over the prefetched `loadUserContext` data.
 */
export function upstreamGuidance(ctx: UpstreamUserContext, budget: number): string {
  const lines: string[] = []
  for (const row of ctx.rows) {
    const refs = wholeUpstreamPointers(
      ctx.skillsByUpstream.get(row.id) ?? [],
      ctx.docsByUpstream.get(row.id) ?? []
    )
    if (refs.length === 0) continue
    const named = refs.slice(0, MAX_REFS_PER_LINE)
    const extra = refs.length - named.length
    lines.push(`- \`${row.slug}\`: ${named.join(', ')}${extra > 0 ? ` +${extra} more` : ''}`)
  }
  if (lines.length === 0) return ''
  const overflow = (n: number) =>
    `- …plus ${n} more upstream${n === 1 ? '' : 's'} with playbooks — check \`list_upstreams.attached_skills\`.`
  const compose = (named: string[], rest: number) =>
    GUIDANCE_HEADER + [...named, ...(rest > 0 ? [overflow(rest)] : [])].join('\n') + '\n\n'
  const full = compose(lines, 0)
  if (full.length <= budget) return full
  // Largest fitting prefix of named lines; the remainder collapses into
  // the overflow pointer. keep = 0 (header + pointer alone) always fits
  // any budget the static-block guard permits.
  for (let keep = lines.length - 1; keep >= 0; keep--) {
    const out = compose(lines.slice(0, keep), lines.length - keep)
    if (out.length <= budget) return out
  }
  return ''
}

/**
 * Tools hidden from the caller by per-tool ACL, with what would unlock
 * each. Powers `list_my_context.restrictedTools` — the discoverability
 * signal that lets the agent say "that tool needs role X" instead of
 * hitting a blank "tool not found". Scoped to upstreams the caller can
 * already SEE (we never reveal a tool on an upstream they can't see).
 * Reads the cached catalogue (no refresh) — best-effort advisory.
 * Takes the caller's visible rows + principals from the caller (the
 * `list_my_context` handler already holds both), and only reads the
 * catalogues of upstreams that actually carry ACL rows — often zero.
 */
export async function restrictedToolsFor(
  env: Env,
  rows: UpstreamServerRow[],
  principals: UserPrincipals
): Promise<McpRestrictedTool[]> {
  const dialable = rows.filter((r) => isDialableTransport(r.transport))
  if (dialable.length === 0) return []
  const aclRows = await listToolAccessForUpstreams(
    env,
    dialable.map((r) => r.id)
  )
  if (aclRows.length === 0) return []
  const acl = indexToolAccess(aclRows)
  // Only upstreams with ACL rows can produce restricted tools; skip the
  // catalogue read for the (common) unrestricted rest.
  const aclUpstreamIds = new Set(aclRows.map((r) => r.upstream_id))
  const toolsByUpstream = await listCachedToolsForUpstreams(env, [...aclUpstreamIds])
  const out: McpRestrictedTool[] = []
  for (const row of dialable) {
    const tools = toolsByUpstream.get(row.id) ?? []
    for (const t of tools) {
      const rules = acl.get(accessKey(row.id, t.tool_name))
      if (!rules || rules.length === 0) continue // open / inherit
      if (isToolAllowed(rules, principals)) continue // caller can call it
      out.push({ upstream: row.slug, tool: t.tool_name, requires: requiresFromRules(rules) })
    }
  }
  return out
}

/**
 * Catalogue for the `describe_upstream(slug)` built-in: one upstream's
 * tools by their NATIVE upstream names, grouped by the upstream's own
 * first-underscore family prefix, each with its callable mangled name +
 * a one-line summary. Cache-only (no dial). ACL-filtered to what the
 * caller can actually call — so it never leaks a tool registration would
 * hide. Returns null when the slug isn't visible to the caller (or
 * doesn't exist) so the handler can emit a single "not found".
 */
export async function describeUpstreamForUser(
  env: Env,
  userId: string,
  slug: string,
  opts?: { family?: string; query?: string }
): Promise<McpUpstreamTools | null> {
  const row = await getUpstreamVisibleToUser(env, userId, { slug })
  if (!row) return null
  const [principals, aclRows, cached, skills, docs] = await Promise.all([
    resolveUserPrincipals(env, userId),
    listToolAccessForUpstream(env, row.id),
    listCachedTools(env, row.id),
    // Published/org attachments only (default includeDrafts=false) — a
    // private draft never leaks onto describe_upstream, matching list_upstreams.
    listSkillsForUpstream(env, row.id),
    listDocsForUpstream(env, row.id)
  ])
  const acl = indexToolAccess(aclRows)
  const visible = visibleTools(row.id, cached, acl, principals)
  const whole = wholeUpstreamAttachments(skills, docs)
  return {
    slug: row.slug,
    displayName: row.display_name,
    toolsCount: visible.length,
    attached_skills: whole.skills,
    attached_docs: whole.docs,
    groups: groupToolsByFamily(row.slug, visible, perToolAttachments(skills, docs), opts)
  }
}

/**
 * Hydrate rows for the `list_upstreams()` built-in. Reports cached
 * tool count + connected state without forcing a connect. Disconnected
 * upstreams (missing user_bearer creds) are returned with `connected:
 * false` so agents know the deep-link to /upstreams.
 */
export async function listUpstreamsForUser(env: Env, userId: string): Promise<ListUpstreamsEntry[]> {
  const rows = (await listUpstreamsVisibleToUser(env, userId)).filter(
    (r): r is UpstreamServerRow & { transport: SupportedTransport } =>
      isDialableTransport(r.transport)
  )
  if (rows.length === 0) return []
  const ids = rows.map((r) => r.id)
  const credIds = rows
    .filter((r) => r.auth_strategy === 'user_bearer' || r.auth_strategy === 'user_oauth')
    .map((r) => r.id)
  const [credStatuses, toolCounts, skillsByUpstream, docsByUpstream, aclRows] = await Promise.all([
    getUserCredentialStatuses(env, userId, credIds),
    countToolsForUpstreams(env, ids),
    listSkillsForUpstreams(env, ids),
    listDocsForUpstreams(env, ids),
    listToolAccessForUpstreams(env, ids)
  ])
  // ACL-aware counts: subtract the tools the caller can't call (same
  // predicate `describe_upstream` uses via `visibleTools`) so the two
  // surfaces can never disagree. Fast path — the common no-ACL case
  // keeps the bare COUNT(*) with no extra reads.
  if (aclRows.length > 0) {
    const acl = indexToolAccess(aclRows)
    const principals = await resolveUserPrincipals(env, userId)
    const aclUpstreamIds = [...new Set(aclRows.map((r) => r.upstream_id))]
    const toolsByUpstream = await listCachedToolsForUpstreams(env, aclUpstreamIds)
    for (const id of aclUpstreamIds) {
      const cached = toolsByUpstream.get(id) ?? []
      toolCounts.set(id, visibleTools(id, cached, acl, principals).length)
    }
  }
  return rows.map((row) => {
    const requiresCred = row.auth_strategy === 'user_bearer' || row.auth_strategy === 'user_oauth'
    const cred = requiresCred
      ? (credStatuses.get(row.id) ?? { present: false, needsReauth: false })
      : { present: true, needsReauth: false }
    // Whole-upstream attachments only (tool_name = ''); per-tool
    // attachments surface via /api/upstreams/:id/tools.
    const attached_skills = (skillsByUpstream.get(row.id) ?? [])
      .filter((s) => s.tool_name === '')
      .map((s) => ({ slug: s.slug, title: s.title }))
    const attached_docs = (docsByUpstream.get(row.id) ?? [])
      .filter((d) => d.tool_name === '')
      .map((d) => ({ id: d.doc_id, slug: d.slug, title: d.title }))
    return {
      slug: row.slug,
      displayName: row.display_name,
      transport: row.transport,
      connected: cred.present,
      ...(cred.needsReauth ? { needsReauth: true } : {}),
      toolsCount: toolCounts.get(row.id) ?? 0,
      requiresAuth: row.auth_strategy,
      attached_skills,
      attached_docs
    }
  })
}

// ----- pure helpers ------------------------------------------------------

export function truncateDescription(s: string, max = 1024): string {
  return s.length > max ? s.slice(0, max - 1) + '…' : s
}

/**
 * Condense a raw upstream tool description into a single-line summary for
 * the `describe_upstream` catalogue. Strips control characters (untrusted
 * model input — same rule as tool registration), collapses the newlines
 * `sanitizeUntrustedText` deliberately keeps into single spaces, and caps
 * the length. Returns '' for a null/empty description. We deliberately do
 * NOT try to extract a "first sentence" — upstream blurbs are riddled with
 * abbreviations ("e.g.", "i.e.", "System.Title") whose trailing dot is
 * followed by a space, so any period-boundary heuristic cuts early on them.
 * A clean flatten + cap is both robust and more informative. Operates on
 * the RAW `row.description` (no `[DisplayName]` prefix — that's added only
 * at registration), so summaries stay clean.
 */
export function summariseToolDescription(desc: string | null, max = 200): string {
  const flat = sanitizeUntrustedText(desc ?? '')
    .replace(/\s+/g, ' ')
    .trim()
  return truncateDescription(flat, max)
}

/**
 * Group an upstream's cached tools by their NATIVE name's first-underscore
 * family prefix, computed from the slug-collapsed name so it matches what
 * the agent sees. Each entry carries the verbatim upstream `name`, the
 * callable mangled `call` (via the same `mangleToolName` rule registration
 * uses — drift-proof), and a one-line `summary`. Optional `family` /
 * `query` filters narrow the result. Families sort alphabetically with the
 * ungrouped ('') bucket last; tools sort by name within a group. Pure.
 */
export function groupToolsByFamily(
  slug: string,
  tools: UpstreamToolRow[],
  attachments: Map<string, ToolAttachments>,
  opts?: { family?: string; query?: string }
): McpUpstreamToolGroup[] {
  const familyFilter = opts?.family?.toLowerCase()
  const queryFilter = opts?.query?.toLowerCase()
  const byFamily = new Map<string, McpUpstreamToolGroup['tools']>()
  for (const t of tools) {
    const family = toolFamily(slug, t.tool_name)
    if (familyFilter !== undefined && family.toLowerCase() !== familyFilter) continue
    const summary = summariseToolDescription(t.description)
    if (
      queryFilter !== undefined &&
      !t.tool_name.toLowerCase().includes(queryFilter) &&
      !summary.toLowerCase().includes(queryFilter)
    ) {
      continue
    }
    const att = attachments.get(t.tool_name)
    const entry = {
      name: t.tool_name,
      call: mangleToolName(slug, t.tool_name),
      summary,
      attached_skills: att?.skills ?? [],
      attached_docs: att?.docs ?? []
    }
    const arr = byFamily.get(family)
    if (arr) arr.push(entry)
    else byFamily.set(family, [entry])
  }
  return [...byFamily.entries()]
    .sort(([a], [b]) => {
      // Ungrouped ('') always last; otherwise alphabetical.
      if (a === '') return 1
      if (b === '') return -1
      return a < b ? -1 : a > b ? 1 : 0
    })
    .map(([family, entries]) => ({
      family,
      tools: entries.sort((a, b) => (a.name < b.name ? -1 : a.name > b.name ? 1 : 0))
    }))
}

/**
 * Filter cached tools down to the ones the caller may actually call, using
 * the exact same per-tool ACL predicate registration applies. Load-bearing
 * for `describe_upstream`: without it the catalogue would leak
 * names/summaries of tools hidden by ACL. Pure.
 */
export function visibleTools(
  upstreamId: string,
  tools: UpstreamToolRow[],
  acl: ReturnType<typeof indexToolAccess>,
  principals: UserPrincipals
): UpstreamToolRow[] {
  return tools.filter((t) => isToolAllowed(acl.get(accessKey(upstreamId, t.tool_name)), principals))
}

/**
 * Whole-upstream attachment pointers (tool_name = '') as ready-to-render
 * ref strings, in skills-then-docs order. These name the org playbook for
 * the WHOLE upstream and feed the server `instructions` leading block
 * (`upstreamGuidance`), whose header names the fetch tools once — so no
 * per-ref `(get_skill)` here, unlike `perToolPointers`, whose refs render
 * standalone on tool descriptions. Per-tool rows (tool_name != '') are
 * skipped here; `perToolPointers` owns those.
 */
export function wholeUpstreamPointers(
  skills: SkillForUpstreamRow[],
  docs: DocForUpstreamRow[]
): string[] {
  return [
    ...skills.filter((s) => s.tool_name === '').map((s) => `skill \`${s.slug}\``),
    ...docs.filter((d) => d.tool_name === '').map((d) => `doc \`${d.slug}\``)
  ]
}

/**
 * Group per-tool attachment pointers (tool_name != '') by upstream tool
 * name. Whole-upstream rows (tool_name = '') are skipped here — they are
 * named in the server `instructions` and `list_upstreams.attached_skills`.
 * Skills and docs are merged into one ordered list per tool so a tool can
 * carry both.
 */
export function perToolPointers(
  skills: SkillForUpstreamRow[],
  docs: DocForUpstreamRow[]
): Map<string, string[]> {
  const out = new Map<string, string[]>()
  const add = (toolName: string, ref: string) => {
    if (toolName === '') return
    const arr = out.get(toolName) ?? []
    arr.push(ref)
    out.set(toolName, arr)
  }
  for (const s of skills) add(s.tool_name, `skill \`${s.slug}\` (get_skill)`)
  for (const d of docs) add(d.tool_name, `doc \`${d.slug}\` (get_doc)`)
  return out
}

/** Structured per-tool attachment refs for one tool (fed into `describe_upstream`). */
export interface ToolAttachments {
  skills: McpAttachedSkillRef[]
  docs: McpAttachedDocRef[]
}

/**
 * Per-tool (tool_name != '') attachments grouped by native upstream tool name,
 * as STRUCTURED data for `describe_upstream` — the agent decides whether to
 * fetch them via get_skill/get_doc. This is the structured replacement for the
 * per-tool imperative that used to ride the tool description. Whole-upstream
 * attachments (tool_name = '') are excluded here; they ride
 * `list_upstreams.attached_skills`. Mirrors `perToolPointers` but emits
 * `{slug,title}` / `{id,slug,title}` objects instead of prose ref strings.
 */
export function perToolAttachments(
  skills: SkillForUpstreamRow[],
  docs: DocForUpstreamRow[]
): Map<string, ToolAttachments> {
  const out = new Map<string, ToolAttachments>()
  const bucket = (toolName: string): ToolAttachments => {
    let b = out.get(toolName)
    if (!b) {
      b = { skills: [], docs: [] }
      out.set(toolName, b)
    }
    return b
  }
  for (const s of skills) {
    if (s.tool_name !== '') bucket(s.tool_name).skills.push({ slug: s.slug, title: s.title })
  }
  for (const d of docs) {
    if (d.tool_name !== '')
      bucket(d.tool_name).docs.push({ id: d.doc_id, slug: d.slug, title: d.title })
  }
  return out
}

/**
 * Whole-upstream (tool_name = '') attachments as structured refs for the
 * `describe_upstream` top level — the same set `list_upstreams` reports,
 * mirrored so a drill-in shows the upstream's governing playbooks alongside
 * its tools. Per-tool rows are excluded here (`perToolAttachments` owns those).
 */
export function wholeUpstreamAttachments(
  skills: SkillForUpstreamRow[],
  docs: DocForUpstreamRow[]
): ToolAttachments {
  return {
    skills: skills.filter((s) => s.tool_name === '').map((s) => ({ slug: s.slug, title: s.title })),
    docs: docs
      .filter((d) => d.tool_name === '')
      .map((d) => ({ id: d.doc_id, slug: d.slug, title: d.title }))
  }
}

/**
 * Per-session registry that hydrates proxied upstream tools onto the
 * `McpServer` alongside the built-ins.
 *
 * Lifecycle:
 *   - `init(server)` runs once per session in `McpSessionDO.init()`.
 *     It enumerates upstreams the caller can reach (visibility +
 *     credentials), decrypts each bearer, ensures the catalogue cache
 *     is fresh, and registers one mangled MCP tool per cached
 *     `upstream_tools` row.
 *   - Tool handlers dispatch through the cached `UpstreamClient` via
 *     `upstream-call-runner.ts`, or through `async-submit.ts` for
 *     tools on the upstream's `authConfig.asyncTools`.
 *   - There is no teardown: sessions are short-lived and the workerd
 *     isolate frees Client state on its own when the DO dies.
 *
 * Catalogue freshness: a row older than `CATALOGUE_TTL_SECONDS` is
 * refreshed inline on first session encounter — accepted as a one-time
 * connect cost so the agent sees a complete `tools/list` immediately.
 * Empty cache (brand-new upstream) is also refreshed inline.
 *
 * The read-models behind `describe_upstream` / `list_upstreams` /
 * `restrictedTools` live in `catalogue-views.ts`.
 */

import type { McpServer } from '@modelcontextprotocol/sdk/server/mcp.js'
import type { Env } from '../env'
import {
  toUpstreamConnection,
  type UpstreamConnection,
  type UpstreamServerRow
} from '../db/queries/upstreams'
import { listCachedTools, listCachedToolsForUpstreams, replaceCachedTools, type UpstreamToolRow } from '../db/queries/upstream-tools'
import type { SkillForUpstreamRow } from '../db/queries/skill-attachments'
import type { DocForUpstreamRow } from '../db/queries/doc-attachments'
import {
  accessKey,
  indexToolAccess,
  listToolAccessForUpstreams,
  resolveUserPrincipals
} from '../db/queries/tool-access'
import { createUpstreamClient } from '../upstream/create-client'
import type { UpstreamClient } from '../upstream/upstream-client'
import { isToolAllowed } from '@ctxlayer/shared'
import { resolveUserUpstreamBearer } from '../upstream/bearer'
import { mangleToolName, unmangleToolName } from './tool-name'
import { firstParty, sanitizeUntrustedText } from './provenance'
import { jsonSchemaToZod } from './json-schema-to-zod'
import { classifyUpstreamError, scrubErrorForStorage } from '../usage/error-detail'
import type { RecordUsageArgs } from '../usage/record'
import { errMessage } from '../util/errors'
import { errText, safeJson } from './tool-result'
import {
  loadUserContext,
  perToolPointers,
  truncateDescription,
  type UpstreamUserContext
} from './catalogue-views'
import {
  callWithHeartbeat,
  runUpstreamCall,
  type ProxyToolExtra
} from './upstream-call-runner'
import { isAsyncTool, submitAsyncJob } from './async-submit'
import { credentialFreshnessError } from './credential-freshness'

// 24h cache TTL per docs/plan/C-upstream-proxy.md §C1.
const CATALOGUE_TTL_SECONDS = 24 * 60 * 60

export class UpstreamProxyRegistry {
  /** upstream_id → live MCP Client */
  private clients = new Map<string, UpstreamClient>()
  /**
   * `accessKey(upstream_id, tool_name)` for every tool this session is
   * allowed to call. Populated at `init()` from the per-tool ACL; also
   * backstops the call handler (defense-in-depth).
   */
  private allowedToolKeys = new Set<string>()

  constructor(
    private readonly env: Env,
    private readonly userId: string,
    // Stage a usage event into the owning DO's SQLite outbox. Awaited on
    // the tool path (cheap: one synchronous insert + an idempotent drain
    // schedule) so durability no longer rides a cancellable `waitUntil`.
    private readonly stageUsage: (args: RecordUsageArgs) => Promise<void>,
    private readonly sessionId: string,
    // Injectable so tests can substitute a fake transport without real
    // network. Defaults to the real factory in production.
    private readonly makeClient: typeof createUpstreamClient = createUpstreamClient
  ) {}

  /**
   * Hydrate the registry and register one MCP tool per cached upstream
   * tool. Safe to call before any built-in tools are registered — the
   * SDK accumulates handlers across calls and the eventual `tools/list`
   * returns the union. Accepts the prefetched per-user context from
   * `loadUserContext` (session init shares it with `upstreamGuidance`);
   * loads it itself when not supplied.
   */
  async init(server: McpServer, ctx?: UpstreamUserContext): Promise<void> {
    const { rows, skillsByUpstream, docsByUpstream } =
      ctx ?? (await loadUserContext(this.env, this.userId))
    await this.registerUpstreams(server, rows, skillsByUpstream, docsByUpstream)
  }

  /**
   * Re-scan the caller's upstreams and grow this session's registered
   * tool set to match reality:
   *   1. Register every tool of any upstream connected AFTER this
   *      session's `init` (a mid-session connect is otherwise invisible
   *      until the MCP client reconnects).
   *   2. Reconcile ALREADY-connected upstreams against the org-global
   *      catalogue — the cache may have been refreshed (or healed from a
   *      degraded `tools/list`) by another session/admin since this
   *      session registered, leaving this session bound to a subset
   *      (2026-08-11 Datadog incident: sessions stuck on 3 of 25 tools).
   *      Newly-visible allowed tools are registered; nothing is ever
   *      unregistered mid-session (ACL revocation is backstopped in the
   *      call handler instead).
   * Idempotent: already-registered tools are skipped, so no tool is
   * double-registered (registering a duplicate name would throw). Emits
   * `tools/list_changed` on the live server when something new registers —
   * a client that honors it surfaces the tools without a reconnect.
   * Returns a summary of what was added on either path.
   */
  async refresh(
    server: McpServer
  ): Promise<{ added: { slug: string; tools: number }[]; loaded: number }> {
    const { rows, skillsByUpstream, docsByUpstream } = await loadUserContext(this.env, this.userId)
    const fresh = rows.filter((r) => !this.clients.has(r.id))
    const added = (
      await this.registerUpstreams(server, fresh, skillsByUpstream, docsByUpstream)
    ).filter((a) => a.tools > 0)
    added.push(
      ...(await this.reconcileConnected(
        server,
        rows.filter((r) => this.clients.has(r.id)),
        skillsByUpstream,
        docsByUpstream
      ))
    )
    if (added.length > 0) {
      // The live session's tool set grew — tell the client to re-read.
      // Belt-and-suspenders: the SDK also emits on `registerTool` when the
      // server is connected, but an explicit send is harmless (an
      // idempotent re-fetch) and covers SDK versions that don't auto-notify.
      try {
        server.server.sendToolListChanged()
      } catch (err) {
        console.error('[upstream-proxy] sendToolListChanged failed:', err)
      }
    }
    return { added, loaded: this.clients.size }
  }

  /**
   * Register tools that appeared in the catalogue after this session
   * bound an upstream (see `refresh` step 2). Re-runs the same
   * freshness check `init` used — `ensureCatalogue` dials only when the
   * cache is empty/stale, reusing this session's live client — then
   * registers every allowed tool not yet in `allowedToolKeys` (the
   * registered set). Per-upstream failures degrade only that upstream.
   */
  private async reconcileConnected(
    server: McpServer,
    rows: UpstreamServerRow[],
    skillsByUpstream: Map<string, SkillForUpstreamRow[]>,
    docsByUpstream: Map<string, DocForUpstreamRow[]>
  ): Promise<{ slug: string; tools: number }[]> {
    if (rows.length === 0) return []
    const [principals, aclRows, cachedByUpstream] = await Promise.all([
      resolveUserPrincipals(this.env, this.userId),
      listToolAccessForUpstreams(
        this.env,
        rows.map((r) => r.id)
      ),
      listCachedToolsForUpstreams(
        this.env,
        rows.map((r) => r.id)
      )
    ])
    const acl = indexToolAccess(aclRows)
    const out: { slug: string; tools: number }[] = []
    for (const row of rows) {
      try {
        const conn = safeConnection(row)
        if (!conn) continue
        const client = this.clients.get(conn.id)
        if (!client) continue
        const tools = await this.ensureCatalogue(conn, client, cachedByUpstream.get(conn.id) ?? [])
        const perTool = perToolPointers(
          skillsByUpstream.get(conn.id) ?? [],
          docsByUpstream.get(conn.id) ?? []
        )
        let count = 0
        for (const t of tools) {
          const key = accessKey(conn.id, t.tool_name)
          if (this.allowedToolKeys.has(key)) continue // registered this session
          if (!isToolAllowed(acl.get(key), principals)) continue // hidden by ACL
          this.allowedToolKeys.add(key)
          this.registerTool(server, conn, t, perTool.get(t.tool_name) ?? [])
          count++
        }
        if (count > 0) out.push({ slug: conn.slug, tools: count })
      } catch (err) {
        console.error(`[upstream-proxy] ${row.slug}: reconcile failed: ${errMessage(err)}`)
      }
    }
    return out
  }

  /**
   * Prepare + register one MCP tool per allowed cached tool for the given
   * upstream rows. Shared by `init` (all visible upstreams) and `refresh`
   * (only the newly-connected ones). Returns per-upstream registered-tool
   * counts in `rows` order — registration is sequential so `tools/list`
   * stays deterministic.
   */
  private async registerUpstreams(
    server: McpServer,
    rows: UpstreamServerRow[],
    skillsByUpstream: Map<string, SkillForUpstreamRow[]>,
    docsByUpstream: Map<string, DocForUpstreamRow[]>
  ): Promise<{ slug: string; tools: number }[]> {
    if (rows.length === 0) return []
    // Resolve the caller's principals + the per-tool ACL + the cached
    // catalogues for every visible upstream once, up front. A tool with
    // no ACL rows inherits the upstream's visibility; a locked tool the
    // caller doesn't match is HIDDEN here (never registered, so the agent
    // never sees it). The allowed-key set also backstops the call handler.
    const [principals, aclRows, cachedByUpstream] = await Promise.all([
      resolveUserPrincipals(this.env, this.userId),
      listToolAccessForUpstreams(
        this.env,
        rows.map((r) => r.id)
      ),
      listCachedToolsForUpstreams(
        this.env,
        rows.map((r) => r.id)
      )
    ])
    const acl = indexToolAccess(aclRows)
    // Per-upstream prep (bearer resolution, client dial, catalogue
    // refresh) runs concurrently; a throw degrades only that upstream.
    // Registration happens sequentially afterwards, in `rows` order, so
    // the tool ordering visible in `tools/list` stays deterministic.
    const prepped = await Promise.all(
      rows.map((row) =>
        this.prepareUpstream(row, cachedByUpstream.get(row.id) ?? []).catch((err) => {
          const msg = errMessage(err)
          console.error(`[upstream-proxy] ${row.slug}: init failed: ${msg}`)
          return null
        })
      )
    )
    const added: { slug: string; tools: number }[] = []
    for (const prep of prepped) {
      if (!prep) continue
      const { conn, client, tools } = prep
      this.clients.set(conn.id, client)
      const skills = skillsByUpstream.get(conn.id) ?? []
      const docs = docsByUpstream.get(conn.id) ?? []
      // Only PER-TOOL pointers (tool_name != '') ride the description now.
      // Whole-upstream playbooks (tool_name = '') are NOT fanned onto every
      // tool anymore — they already live in the server `instructions`
      // (`upstreamGuidance`) and in `list_upstreams.attached_skills`, so
      // repeating them on each tool was redundant noise. Per-tool bindings also
      // have a structured home in `describe_upstream`; this description line is
      // just passive discoverability for the tool-specific ones.
      const perTool = perToolPointers(skills, docs)
      let count = 0
      for (const t of tools) {
        const key = accessKey(conn.id, t.tool_name)
        if (!isToolAllowed(acl.get(key), principals)) continue // hidden by ACL
        this.allowedToolKeys.add(key)
        this.registerTool(server, conn, t, perTool.get(t.tool_name) ?? [])
        count++
      }
      added.push({ slug: conn.slug, tools: count })
    }
    return added
  }

  // ----- internals ------------------------------------------------------

  private resolveBearer(row: UpstreamServerRow, conn: UpstreamConnection): Promise<string | null> {
    return resolveUserUpstreamBearer(this.env, row, conn, this.userId)
  }

  /**
   * Resolve credentials, dial the upstream, and ensure its catalogue is
   * fresh. Returns null to skip the upstream (bad row, missing creds,
   * empty catalogue); throws propagate to the per-upstream catch in
   * `init` so one upstream's failure degrades only that upstream.
   */
  private async prepareUpstream(
    row: UpstreamServerRow,
    cached: UpstreamToolRow[]
  ): Promise<{ conn: UpstreamConnection; client: UpstreamClient; tools: UpstreamToolRow[] } | null> {
    const conn = safeConnection(row)
    if (!conn) return null
    const bearer = await this.resolveBearer(row, conn)
    if (conn.authStrategy !== 'none' && bearer === null) return null

    const client = this.makeClient(conn, bearer)
    const tools = await this.ensureCatalogue(conn, client, cached)
    if (tools.length === 0) {
      // Empty even after refresh — log and skip; user sees built-ins only.
      console.warn(`upstream ${conn.slug} returned no tools after refresh`)
      await client.close()
      return null
    }
    return { conn, client, tools }
  }

  private async ensureCatalogue(
    conn: UpstreamConnection,
    client: UpstreamClient,
    cached: UpstreamToolRow[]
  ): Promise<UpstreamToolRow[]> {
    // Staleness is derived from the prefetched rows (cached_at rides on
    // every row), so the fresh path costs no extra round trip.
    const cachedAt = cached.length === 0 ? null : Math.max(...cached.map((t) => t.cached_at))
    const stale = cachedAt === null || Date.now() / 1000 - cachedAt > CATALOGUE_TTL_SECONDS
    if (!stale) return cached
    try {
      // Reuse the persistent client this registry already opened — avoids
      // a second handshake just to fetch the catalogue.
      const tools = await client.listTools()
      const res = await replaceCachedTools(this.env, conn.id, tools)
      if (res.rejectedShrink) {
        console.warn(
          `[catalogue] ${conn.slug}: refresh returned ${res.rejectedShrink.incoming} tools vs ` +
            `${res.rejectedShrink.prior} cached — suspect shrink rejected, serving prior catalogue`
        )
      }
    } catch (err) {
      const msg = errMessage(err)
      console.error(`[catalogue] ${conn.slug}: tools/list failed: ${msg}`)
      // Fall back to whatever cache we have, even if stale.
    }
    return listCachedTools(this.env, conn.id)
  }

  private registerTool(
    server: McpServer,
    conn: UpstreamConnection,
    row: UpstreamToolRow,
    pointers: string[] = []
  ): void {
    const mangled = mangleToolName(conn.slug, row.tool_name)
    // Upstream-supplied descriptions are untrusted model input. Strip
    // control characters (which can hide injected instructions or
    // disrupt agent rendering) before forwarding. We deliberately do
    // NOT try to detect prompt-injection content — that's the model's
    // job; ours is to keep the wire bytes well-formed.
    let description = truncateDescription(
      sanitizeUntrustedText(`[${conn.displayName}] ${row.description ?? ''}`)
    )
    // Append org-curated per-tool attachment pointers. These are
    // first-party (slug strings we control), not upstream input, so they
    // need no sanitisation. Truncate the base description first to
    // reserve room — the pointer is the binding guidance and must
    // survive the 1024-char cap even when the upstream blurb is long.
    if (pointers.length > 0) {
      // Descriptive disclosure, NOT an imperative: name the org playbooks that
      // exist for this tool and leave the choice to the agent. The old
      // "consult X before using this tool" framing was a command smuggled
      // through the data plane — well-behaved agents (correctly) treat tool
      // metadata as untrusted and resist it, so it was both brittle and
      // eroding of the very boundary that protects callers from a malicious
      // upstream's descriptions. The structured home for these is
      // `describe_upstream` (per-tool `attached_skills`/`attached_docs`); this
      // line is just passive discoverability on the one field every client
      // renders. Wrapped in the ⟦ctxlayer⟧ provenance marker (first-party,
      // unforgeable — the upstream description above it is defanged).
      const suffix = `\n\n${firstParty(`Related org playbooks (optional context): ${pointers.join(', ')}.`)}`
      description = truncateDescription(description, 1024 - suffix.length) + suffix
    }
    let inputSchemaJson: unknown = {}
    try {
      inputSchemaJson = JSON.parse(row.input_schema)
    } catch {
      // Bad cache row; treat as no schema. Tool still callable.
    }
    const converted = jsonSchemaToZod(inputSchemaJson)
    const inputSchema = converted.shape ?? converted.zod
    // Close over the real upstream tool name from the cache row. The
    // mangled name we expose to the agent can drop the redundant
    // `${slug}-` prefix (see `mangleToolName`), so `unmangleToolName`
    // would no longer round-trip — we rely on `row.tool_name` here
    // instead. Sanity-check the mangled name shape only.
    const upstreamToolName = row.tool_name
    const handler = async (args: unknown, extra?: ProxyToolExtra) => {
      if (!unmangleToolName(mangled)) return errText(`bad tool name: ${mangled}`)
      // Defense-in-depth: only ACL-allowed tools are ever registered, so
      // this can't fire on the normal path. It backstops a future
      // refactor that registers more broadly. Generic code to the agent;
      // the real reason is logged server-side per the no-leak rule.
      if (!this.allowedToolKeys.has(accessKey(conn.id, upstreamToolName))) {
        console.warn(`[tool-acl] blocked ${conn.slug}.${upstreamToolName} for user ${this.userId}`)
        return errText('access_denied: tool restricted')
      }
      const client = this.clients.get(conn.id)
      if (!client) return errText(`upstream ${conn.slug} not connected`)
      // A6: user-scoped creds were bound at session init — one point-read
      // per call so a mid-session disconnect / reauth flag blocks now, not
      // when the session dies. Also gates async SUBMITs (below).
      const staleCred = await credentialFreshnessError(this.env, this.userId, conn)
      if (staleCred) {
        console.warn(
          `[cred-freshness] blocked ${conn.slug}.${upstreamToolName} for user ${this.userId}`
        )
        return errText(staleCred)
      }
      const t0 = Date.now()
      const reqJson = safeJson(args)
      let status: 'ok' | 'error' | 'timeout' = 'ok'
      let truncated = false
      let respJson = ''
      // Set only on failures — a coarse class + the raw detail (scrubbed
      // for storage in the `finally`). Drives the usage error table.
      let errorCode: string | undefined
      let errorDetail: string | undefined
      try {
        // Async-eligible tools (per `authConfig.asyncTools`) can run far
        // longer than an interactive client's request timeout — Claude
        // Desktop hard-caps at ~180s and does not reset on progress, so no
        // server-side keepalive helps. Run them out-of-band: enqueue a job,
        // return a token immediately, and let the ctxlayer-jobs consumer run
        // the full call (poll_task fetches the result). A retried identical
        // call returns the cached result. See docs/plan/I-upstream-resilience §I9.
        if (isAsyncTool(conn, upstreamToolName)) {
          try {
            const sub = await submitAsyncJob(
              this.env,
              { userId: this.userId, sessionId: this.sessionId },
              conn,
              upstreamToolName,
              args
            )
            respJson = sub.respJson
            return sub.surface
          } catch (err) {
            // A failed submit (D1 insert, queue send) reaches the agent as a
            // thrown error — record it as one, not as a zero-byte 'ok'.
            status = 'error'
            errorDetail = errMessage(err)
            errorCode = classifyUpstreamError('error', errorDetail)
            throw err
          }
        }
        const outcome = await runUpstreamCall({
          slug: conn.slug,
          toolName: upstreamToolName,
          upstreamUrl: conn.url,
          maxResponseBytes: conn.authConfig.maxResponseBytes,
          run: () => callWithHeartbeat(extra, () => client.callTool(upstreamToolName, args))
        })
        respJson = outcome.respJson
        status = outcome.status
        truncated = outcome.truncated
        errorCode = outcome.errorCode
        errorDetail = outcome.errorDetail
        return outcome.surface
      } finally {
        await this.stageUsage({
          userId: this.userId,
          sessionId: this.sessionId,
          upstreamId: conn.id,
          tool: mangled,
          reqJson,
          respJson,
          latencyMs: Date.now() - t0,
          status,
          truncated,
          errorCode,
          errorMessage: errorDetail != null ? scrubErrorForStorage(errorDetail) : undefined
        })
      }
    }
    // The SDK's `registerTool` overload requires a Zod schema at the
    // type level but happily accepts our derived shape at runtime.
    // Single cast on the call keeps the handler closed-over types
    // intact (alternative: cast the inputSchema to `never`, which
    // collapses the callback signature to `() => ...`).
    ;(
      server.registerTool as unknown as (
        name: string,
        cfg: { title: string; description: string; inputSchema: unknown },
        cb: (args: unknown, extra: ProxyToolExtra) => unknown
      ) => unknown
    )(
      mangled,
      // title = mangled so the human-facing label matches the
      // agent-callable name (and surfaces the upstream slug). Falls
      // out of the same `<slug>__<tool>` rule the admin upstreams
      // page's "Agent-visible name" column uses, after the redundant-
      // prefix collapse (`notion__search`, not `notion__notion-search`).
      { title: mangled, description, inputSchema },
      handler
    )
  }
}

function safeConnection(row: UpstreamServerRow): UpstreamConnection | null {
  try {
    return toUpstreamConnection(row)
  } catch {
    return null
  }
}

/**
 * MCP surface for skills: list_skills + get_skill tools plus a
 * `mcp://ctxlayer/skills/{slug}` resource template. Extracted from
 * session-do.ts to keep that file focused on session lifecycle.
 *
 * All three only ever surface `status='published'` skills; drafts and
 * archived stay admin-only via the SPA. Non-admin callers cannot reach
 * drafts through any MCP path.
 */

import type { McpServer } from '@modelcontextprotocol/sdk/server/mcp.js'
import { ResourceTemplate } from '@modelcontextprotocol/sdk/server/mcp.js'
import type { Env } from '../env'
import { listPublishedSkills } from '../db/queries/skills'
import { listAttachmentsForSkills } from '../db/queries/skill-attachments'
import { type McpSkillSummary, McpListSkillsResult, builtinToolMeta } from '@ctxlayer/shared'
import { BUILTIN_INPUT_SHAPES } from './builtin-schemas'
import { loadPublishedSkillMarkdown } from './skill-render'
import { registerSkillSep2640 } from './skill-sep2640'
import { listUpstreamsVisibleToUser } from '../db/queries/upstreams'
import {
  draftedForUpstreams,
  missingUpstreams,
  requiredUpstreamSlugs,
  skillAccessAdvisory
} from '../skills/skill-requires'
import { errText } from './tool-result'

export type RecWrap = <T extends { content?: unknown; isError?: boolean }>(
  tool: string,
  args: unknown,
  exec: () => Promise<T>
) => Promise<T>

export function registerSkillMcp(
  server: McpServer,
  env: Env,
  rec: RecWrap,
  getUserId: () => string | undefined
): void {
  // list_skills + get_skill title/description are sourced from BUILTIN_TOOLS
  // in `packages/shared/src/builtin-tools.ts` via builtinToolMeta (single
  // source for /api/tools + the agent surface). Schemas + handlers stay here.
  server.registerTool(
    'list_skills',
    {
      ...builtinToolMeta('list_skills'),
      // structuredContent must be an object, so the summary array is wrapped
      // under `skills`; the text `content` keeps the bare array for back-compat.
      outputSchema: { skills: McpListSkillsResult }
    },
    () =>
      rec('list_skills', undefined, async () => {
        const rows = await listPublishedSkills(env)
        // One IN-query for every skill's attachments instead of one
        // round trip per skill.
        const attachmentsBySkill = await listAttachmentsForSkills(
          env,
          rows.map((r) => r.id)
        )
        // The caller's reachable upstreams, fetched once, to flag per-skill
        // which required upstreams they can't currently reach.
        const userId = getUserId()
        const visible = userId
          ? new Set((await listUpstreamsVisibleToUser(env, userId)).map((u) => u.slug))
          : new Set<string>()
        // Typed against the shared MCP contract (`McpSkillSummary`).
        const summaries: McpSkillSummary[] = rows.map((row) => {
          const atts = attachmentsBySkill.get(row.id) ?? []
          const requires = requiredUpstreamSlugs(
            atts.map((a) => a.upstream_slug),
            draftedForUpstreams(row.drafter_meta)
          )
          return {
            slug: row.slug,
            name: row.slug,
            title: row.title,
            description: row.description,
            attached_to: atts.map((a) => ({
              upstream_slug: a.upstream_slug,
              tool_name: a.tool_name || null
            })),
            requires_upstreams: requires,
            missing_upstreams: missingUpstreams(requires, visible)
          }
        })
        return {
          content: [{ type: 'text', text: JSON.stringify(summaries, null, 2) }],
          structuredContent: { skills: summaries }
        }
      })
  )

  server.registerTool(
    'get_skill',
    { ...builtinToolMeta('get_skill'), inputSchema: BUILTIN_INPUT_SHAPES.get_skill },
    (args) =>
      rec('get_skill', args, async () => {
        const md = await loadPublishedSkillMarkdown(env, args.slug)
        if (md == null) return errText(`skill not found: ${args.slug}`)
        // Append an access advisory when the caller can't reach an upstream
        // this skill depends on, so the agent tells the user to connect it.
        const advisory = await skillAccessAdvisory(env, getUserId(), args.slug)
        return { content: [{ type: 'text', text: md + advisory }] }
      })
  )

  // mcp://ctxlayer/skills/{slug} — resource template enabling resource-
  // capable agents to discover and read skills without invoking a tool.
  const template = new ResourceTemplate('mcp://ctxlayer/skills/{slug}', {
    list: async () => {
      const rows = await listPublishedSkills(env)
      return {
        resources: rows.map((r) => ({
          uri: `mcp://ctxlayer/skills/${r.slug}`,
          name: r.title,
          description: r.description,
          mimeType: 'text/markdown'
        }))
      }
    }
  })

  server.registerResource(
    'skill',
    template,
    {
      title: 'Curated skills',
      description: 'Procedural playbooks the agent loads on demand.'
    },
    async (uri: URL, variables: { slug?: string | string[] }) => {
      const slugVar = variables.slug
      const slug = Array.isArray(slugVar) ? slugVar[0] : slugVar
      if (!slug) {
        return { contents: [{ uri: uri.toString(), text: 'missing skill slug' }] }
      }
      const md = await loadPublishedSkillMarkdown(env, slug)
      if (md == null) {
        return { contents: [{ uri: uri.toString(), text: `skill not found: ${slug}` }] }
      }
      return {
        contents: [{ uri: uri.toString(), mimeType: 'text/markdown', text: md }]
      }
    }
  )

  // Additive SEP-2640 future-proofing: serve the same skills over the
  // standard `skill://` scheme + a discovery document, and advertise the
  // skills extension capability. See skill-sep2640.ts.
  registerSkillSep2640(server, env)
}

// ----- helpers -----------------------------------------------------------

/**
 * Skill read helper for the agent-facing MCP surface. Lives apart from
 * skill-mcp.ts so both the canonical surface (list_skills/get_skill +
 * `mcp://ctxlayer/skills/{slug}`) and the SEP-2640 `skill://` surface can
 * import it without a circular dependency. SKILL.md text comes from the
 * shared renderer in skills/skill-md.ts.
 */

import type { Env } from '../env'
import { getSkillBySlug } from '../db/queries/skills'
import { readSnapshot } from '../storage/skills-r2'
import { renderBlocksToMarkdown } from '../rag/markdown'
import { renderSkillMd } from '../skills/skill-md'

/**
 * Load an org-shared published skill's rendered SKILL.md markdown by
 * slug, or null if the slug is unknown / not org-shared+published.
 * Single-sourced read shared by get_skill and both resource surfaces
 * (mcp:// and skill://) so the visibility gate and rendering never drift
 * between them. Private skills never surface here — owner-scoped MCP
 * access (draft-and-test) threads a caller id in a later phase.
 */
export async function loadPublishedSkillMarkdown(env: Env, slug: string): Promise<string | null> {
  const row = await getSkillBySlug(env, slug)
  if (!row || row.status !== 'published' || row.visibility !== 'org') return null
  const content = await readSnapshot(env, row.id)
  const body = content ? renderBlocksToMarkdown(content.blocks) : ''
  // Agent-facing (no provenance comment); shared renderer keeps the shape
  // identical to the web SKILL.md download.
  return renderSkillMd(
    { slug: row.slug, name: row.slug, description: row.description, triggerText: row.trigger_text, bodyMd: body },
    {}
  )
}

