/**
 * Tiny markdown → BlockNote-blocks converter. Turns the markdown body an
 * agent hands to the `save_draft_skill` tool into the block tree the skill
 * store + SPA editor round-trip. Ported (verbatim) from the CLI's
 * `drafter/markdown-to-blocks.ts` so the CLI drafting path can be retired;
 * dependency-free by design.
 *
 * Handles at block level: paragraphs, ATX headings (#…######), bullet
 * lists (`-` / `*`), numbered lists (`1.`), fenced code blocks
 * (```...```). Inline within a block: backtick-code, **bold**, *italic*,
 * _italic_, [text](url).
 *
 * Round-trip target is the worker's renderBlocksToMarkdown
 * (apps/worker/src/rag/markdown.ts): the markdown we emit from the blocks
 * we build should equal (or near-equal) the source markdown. So we mirror
 * the inline styles + link shapes that renderer already serialises —
 * `styles.{bold,italic,code}` and a `link` leaf — and avoid constructs it
 * can't emit.
 *
 * Out of scope: blockquotes, tables, images, HTML, nested lists, setext
 * headings, hard breaks, escapes. The author can polish in the SPA editor.
 */

interface TextLeaf {
  type: 'text'
  text: string
  styles: {
    bold?: boolean
    italic?: boolean
    code?: boolean
  }
}

interface LinkLeaf {
  type: 'link'
  href: string
  content: TextLeaf[]
}

type Inline = TextLeaf | LinkLeaf

interface Block {
  type: string
  props?: Record<string, unknown>
  content: Inline[]
}

export function markdownToBlocks(md: string): Block[] {
  const out: Block[] = []
  const lines = md.replace(/\r\n/g, '\n').split('\n')
  let i = 0

  while (i < lines.length) {
    const line = lines[i] ?? ''

    if (line.trim() === '') {
      i++
      continue
    }

    // Fenced code block: ```lang ... ```
    const fenceMatch = line.match(/^```(\w*)\s*$/)
    if (fenceMatch) {
      const lang = fenceMatch[1] ?? ''
      const buf: string[] = []
      i++
      while (i < lines.length && !/^```\s*$/.test(lines[i] ?? '')) {
        buf.push(lines[i] ?? '')
        i++
      }
      if (i < lines.length) i++ // consume closing fence
      out.push({
        type: 'codeBlock',
        props: { language: lang || 'text' },
        // Code blocks are literal — never run through the inline parser.
        content: [{ type: 'text', text: buf.join('\n'), styles: {} }]
      })
      continue
    }

    // ATX heading
    const headingMatch = line.match(/^(#{1,6})\s+(.+?)\s*#*\s*$/)
    if (headingMatch) {
      out.push({
        type: 'heading',
        props: { level: headingMatch[1]!.length },
        content: parseInline(headingMatch[2]!)
      })
      i++
      continue
    }

    // Bullet list (consume contiguous lines starting with - or *)
    if (/^[-*]\s+/.test(line)) {
      while (i < lines.length && /^[-*]\s+/.test(lines[i] ?? '')) {
        const item = (lines[i] ?? '').replace(/^[-*]\s+/, '')
        out.push({
          type: 'bulletListItem',
          content: parseInline(item)
        })
        i++
      }
      continue
    }

    // Numbered list
    if (/^\d+\.\s+/.test(line)) {
      while (i < lines.length && /^\d+\.\s+/.test(lines[i] ?? '')) {
        const item = (lines[i] ?? '').replace(/^\d+\.\s+/, '')
        out.push({
          type: 'numberedListItem',
          content: parseInline(item)
        })
        i++
      }
      continue
    }

    // Paragraph: greedy until blank line or block-starter
    const buf: string[] = [line]
    i++
    while (i < lines.length) {
      const l = lines[i] ?? ''
      if (
        l.trim() === '' ||
        /^#{1,6}\s+/.test(l) ||
        /^[-*]\s+/.test(l) ||
        /^\d+\.\s+/.test(l) ||
        /^```/.test(l)
      ) {
        break
      }
      buf.push(l)
      i++
    }
    out.push({
      type: 'paragraph',
      content: parseInline(buf.join(' ').trim())
    })
  }
  return out
}

// ----- inline parser ----------------------------------------------------

/**
 * Tokenise a single line of inline markdown into the leaf shape the
 * BlockNote renderer in apps/worker/src/rag/markdown.ts knows how to emit
 * back: `{type:'text', text, styles:{...}}` and `{type:'link', href,
 * content:[...]}`.
 *
 * Construct precedence (left-to-right, longest-match-first per offset):
 *   1. Inline code  `code`
 *   2. Bold         **text**
 *   3. Italic       *text* or _text_
 *   4. Link         [text](url)
 *   5. Plain text   anything else
 *
 * No nesting. The pre-styled segments stay flat — sufficient for
 * round-tripping the formats most authored skills use.
 */
function parseInline(text: string): Inline[] {
  const out: Inline[] = []
  let buf = ''
  let i = 0

  const flushBuf = () => {
    if (buf.length > 0) {
      out.push({ type: 'text', text: buf, styles: {} })
      buf = ''
    }
  }

  while (i < text.length) {
    const ch = text[i]

    // 1. Inline code: `…`
    if (ch === '`') {
      const end = text.indexOf('`', i + 1)
      if (end > i) {
        flushBuf()
        out.push({
          type: 'text',
          text: text.slice(i + 1, end),
          styles: { code: true }
        })
        i = end + 1
        continue
      }
    }

    // 2. Bold: **…**
    if (ch === '*' && text[i + 1] === '*') {
      const end = text.indexOf('**', i + 2)
      if (end > i + 1) {
        const inner = text.slice(i + 2, end)
        // Avoid empty / whitespace-only matches that aren't real markdown.
        if (inner.trim()) {
          flushBuf()
          out.push({
            type: 'text',
            text: inner,
            styles: { bold: true }
          })
          i = end + 2
          continue
        }
      }
    }

    // 3. Italic: *…* or _…_ (single-char delimiters)
    if (ch === '*' || ch === '_') {
      const delim = ch
      // Require word-boundary-ish: don't match `_` inside identifiers.
      // For `*`, also skip when preceded by another `*` (handled by bold).
      const prev = i > 0 ? text[i - 1] : ' '
      if (
        prev !== delim &&
        (delim === '*' || !/\w/.test(prev ?? ' ')) &&
        text[i + 1] !== delim &&
        text[i + 1] !== ' '
      ) {
        const end = findInlineEnd(text, i + 1, delim)
        if (end > i + 1) {
          const inner = text.slice(i + 1, end)
          if (inner.trim()) {
            flushBuf()
            out.push({
              type: 'text',
              text: inner,
              styles: { italic: true }
            })
            i = end + 1
            continue
          }
        }
      }
    }

    // 4. Link: [text](url)
    if (ch === '[') {
      const close = text.indexOf(']', i + 1)
      if (close > i && text[close + 1] === '(') {
        const urlEnd = text.indexOf(')', close + 2)
        if (urlEnd > close + 1) {
          flushBuf()
          out.push({
            type: 'link',
            href: text.slice(close + 2, urlEnd),
            content: [{ type: 'text', text: text.slice(i + 1, close), styles: {} }]
          })
          i = urlEnd + 1
          continue
        }
      }
    }

    // 5. Plain
    buf += ch
    i++
  }
  flushBuf()
  if (out.length === 0) out.push({ type: 'text', text: '', styles: {} })
  return out
}

/**
 * Find the matching closing delimiter for italic (`*` or `_`). Required
 * because the opening test already enforced word-boundary semantics on the
 * LEADING side; the closer must satisfy the symmetric rule so we don't
 * partially-match inside an identifier.
 */
function findInlineEnd(text: string, from: number, delim: string): number {
  let pos = from
  while (pos < text.length) {
    const idx = text.indexOf(delim, pos)
    if (idx < 0) return -1
    const after = idx + 1 < text.length ? text[idx + 1] : ' '
    if (delim === '_' && after && /\w/.test(after)) {
      pos = idx + 1
      continue
    }
    if (delim === '*' && after === '*') {
      // Probably bold's opening **; skip past.
      pos = idx + 2
      continue
    }
    return idx
  }
  return -1
}

/**
 * Registry of post-processors for upstream isError tool results. Each
 * entry is gated on UPSTREAM IDENTITY (URL host) before its text
 * matcher ever runs — a bare regex like /single sign-?on/ must not fire
 * a GitHub-branded playbook (with a GitHub error code) on a Datadog or
 * Notion error that happens to use the same phrase.
 *
 * Runs INSIDE `runUpstreamCall`, before the sanitiser and the size cap
 * (nudge text is first-party ⟦ctxlayer⟧-marked; sanitising it would
 * strip the marker).
 *
 * This module also owns the July-review §1a scrub (`scrubErrorContent`):
 * isError result text is deliberately forwarded to the agent (tool errors
 * are functionally necessary diagnostics), but credential SHAPES in it —
 * Authorization header echoes, bearer blobs, JWTs, well-known vendor token
 * prefixes — are redacted first. Unlike the processors above it is not
 * identity-gated (a leaked credential is a leaked credential regardless of
 * which upstream echoed it) and it transforms rather than replaces, so its
 * output stays on the normal sanitise path. Deliberately narrow: hostnames,
 * paths and status text pass through untouched so diagnostics stay useful.
 */

import type { UsageErrorCode } from '@ctxlayer/shared'
import { githubOrgAccessNudge } from './github-nudges'

/** Identity of the upstream a result came from, for the appliesTo gate. */
export interface UpstreamRef {
  slug: string
  /** The upstream's registered URL; absent only in defensive callers. */
  url?: string
}

export interface ErrorResultRewrite {
  text: string
  errorCode: UsageErrorCode
}

interface ErrorResultProcessor {
  name: string
  appliesTo(ref: UpstreamRef): boolean
  process(raw: string, ref: UpstreamRef): ErrorResultRewrite | null
}

/** True when the upstream URL points at GitHub's API/MCP surface. */
function isGithubHost(url: string | undefined): boolean {
  if (!url) return false
  let host: string
  try {
    host = new URL(url).hostname.toLowerCase()
  } catch {
    return false
  }
  return (
    host === 'github.com' ||
    host.endsWith('.github.com') ||
    host === 'githubcopilot.com' ||
    host.endsWith('.githubcopilot.com')
  )
}

const PROCESSORS: ErrorResultProcessor[] = [
  {
    name: 'github-org-access',
    appliesTo: (ref) => isGithubHost(ref.url),
    process: (raw, ref) => githubOrgAccessNudge(raw, ref.slug)
  }
]

/**
 * Run the registered processors for this upstream, most-specific first;
 * the first rewrite wins. Returns null when no processor applies or
 * matches — the caller keeps the (sanitised) original result.
 */
export function postProcessErrorResult(ref: UpstreamRef, raw: string): ErrorResultRewrite | null {
  for (const p of PROCESSORS) {
    if (!p.appliesTo(ref)) continue
    const rewrite = p.process(raw, ref)
    if (rewrite) return rewrite
  }
  return null
}

/**
 * Credential shapes redacted from isError result text (July review §1a).
 * High-precision on purpose: every pattern anchors on either an auth
 * keyword or a vendor prefix plus a long token blob, so ordinary error
 * prose ("token expired", "bearer of…") can't match. Broadening any of
 * these risks blunting genuinely useful upstream diagnostics — the
 * review explicitly weighed and rejected an aggressive scrub.
 */
const CREDENTIAL_SHAPES: RegExp[] = [
  // `Authorization: Bearer <anything>` header echoes (any scheme value length —
  // the header name itself marks the value as a credential).
  /\bauthorization\s*[:=]\s*(?:bearer|basic|token)\s+[^\s"'`,;]+/gi,
  // Bare `Bearer <long-blob>` / `token <long-blob>` outside a header echo.
  /\b(?:bearer|token)\s+[A-Za-z0-9\-._~+/]{20,}=*/gi,
  // JWT triplet (header.payload.signature).
  /\beyJ[A-Za-z0-9_-]{8,}\.[A-Za-z0-9_-]{8,}\.[A-Za-z0-9_-]{8,}/g,
  // Vendor-prefixed tokens: GitHub, Slack, OpenAI-style sk-, AWS access key id.
  /\b(?:gh[pousr]_|github_pat_)[A-Za-z0-9_]{20,}/g,
  /\bxox[baprs]-[A-Za-z0-9-]{10,}/g,
  /\bsk-[A-Za-z0-9_-]{20,}/g,
  /\bAKIA[0-9A-Z]{16}\b/g
]

/** Redact credential shapes from one string. Exported for tests. */
export function scrubCredentialShapes(text: string): string {
  let out = text
  for (const re of CREDENTIAL_SHAPES) out = out.replace(re, '[redacted-credential]')
  return out
}

/**
 * Scrub an isError result's `content` before ANYTHING downstream reads it —
 * the agent-facing surface, usage `respJson`/`error_detail`, and the
 * async_jobs row `poll_task` replays all derive from the return value, so
 * this is the single write site. Handles the MCP-idiomatic error shapes
 * (text-item array, bare string); other shapes pass through to the normal
 * sanitise path unchanged. Never applied to non-error results: a legitimate
 * tool result may contain secret-shaped data the caller asked to read.
 */
export function scrubErrorContent(content: unknown): unknown {
  if (typeof content === 'string') return scrubCredentialShapes(content)
  if (Array.isArray(content)) {
    return content.map((item) =>
      item && typeof item === 'object' && typeof (item as { text?: unknown }).text === 'string'
        ? { ...item, text: scrubCredentialShapes((item as { text: string }).text) }
        : item
    )
  }
  return content
}

