      <Panel
        title="Errors"
        subtitle="Individual failed tool calls — credential-scrubbed root detail."
      >
        <ErrorsTable rows={data.recentErrors} range={range} />
      </Panel>
      {data.asyncSummary.total > 0 && (
        <Panel
