          if (r.skippedIncompleteIndex) {
            console.warn('[cron] oauth-client prune skipped: grant index incomplete')
          } else {
            console.log(
              `[cron] pruned ${r.deleted}/${r.orphans} orphan oauth clients ` +
                `(scanned ${r.scanned}, ${r.failed} delete failures)`
            )
